// Build 17: the AI squad is the player's choice in Story, Skirmish and Story co-op (three squadmates unless unticked).
// Build 18, standing decision: Ambush never has AI squadmates, under any setting; there the only teammate is a real player. squadPref holds the choice for each mode (never one value for all, so a
// choice made for one mode cannot leak into another); squadActive is what the mission being played was deployed with. In
// co-op the host's choice governs: it travels with the host's menu choice and with the deployment, and the guest's page
// uses it (hostSquad) instead of its own. The co-op teammate is a real player and is never part of this.
const squadPref={story:true,skirmish:true,coop:true};
function guestSession(){return !!peer.connected&&peer.role==='guest'&&(mode==='coop'||mode==='ambush'||mode==='skirmish');}
function squadFor(m){return m!=='ambush'&&squadPref[m]===true;}
function squadWanted(){return mode==='ambush'?false:guestSession()&&hostSquad!==null?hostSquad:squadFor(mode);}
function squadNote(){const on=squadWanted();return mode==='ambush'||on?'':mode==='skirmish'?'Squad off: Skirmish is built for a squad of four. Expect a much harder fight.':'Squad off: Story missions are built for four. Expect a much harder fight.';}
const AMBUSH_SOLO_BRIEF='Ambush: alone, survive wave after wave in the courtyard west of the field office. No squad: every kill, point and risk is yours. There is no win, only how long you last. Kills earn points to open new areas and buy rifles, magazines and dressings; from wave 5 you can extract between waves and bank your points, or stay for a bigger bank.';
