function buyer(who){return who==='mate'?{who,pos:remote.g.position,bank:amb.mate,gun:remoteGun,weapon:remoteWeapon,dressings:remote.heals,inHand:remoteConfig(),holding:remoteHand()}:{who,pos:player,bank:amb,gun:gunId,weapon,dressings:bandages,inHand:handConfig(),holding:hand()};}
function ambushOpenGate(id){const d=amb,g=d.gates.get(id);if(!g)return false;removeGate(g);d.gates.delete(id);d.open.add(g.gate.opens);ambushEdges();ambushMarkings();worldChanged();return true;}
// The purchase in reach: a closed barricade's timber section (from inside the open arena) or an open area's weapon crate.
function ambushNear(who='me'){const d=amb,u=buyer(who),at=u.pos;if(u.bank.down||!inArena(d.open,at.x,at.z,.3))return null;
 for(const {gate} of d.gates.values())if(d.open.has(gate.from)&&Math.hypot(at.x-gate.station[0],at.z-gate.station[1])<2.8)return {kind:'gate',gate,price:gate.price};
 // At a crate: E buys its rifle (loaded with rifleMagazines magazines within the rifle's reserve limit) unless you hold it; B buys
 // one magazine for the rifle you hold and N one field dressing, both at the wave's price (Build 11/12).
 for(const {st} of d.stations)if(d.open.has(st.area)&&Math.hypot(at.x-st.at[0],at.z-st.at[1])<2.2){const held=u.inHand,wave=Math.max(1,d.wave),mag={config:held,price:magazinePrice(held,wave),rounds:held.capacity,full:u.holding.reserve>=held.reserve},dressing={price:dressingPrice(wave),full:u.dressings>=AMBUSH.dressingMax};return u.gun===st.weapon?{kind:'crate',st,price:null,mag,dressing}:{kind:'weapon',st,price:st.price,mag,dressing};}
 return null;}
// The crate prompt (Build 12): the rifle on sale with its trade-off in plain words, a blank line, then your own kit: the rifle
// you hold with reserve and dressings, and the B (magazine) and N (dressing) purchases with this wave's prices.
function ambushPrompt(){const n=ambushNear();if(!n)return '';const need=p=>amb.points<p?` (NEED ${p-amb.points} MORE)`:'';
 if(n.kind==='gate')return `${keyName(KEYS.interact)} · CLEAR BARRICADE TO ${areaById(n.gate.opens).name.toUpperCase()} · ${n.price} PTS${need(n.price)}`;
 const held=handConfig(),m=n.mag,dr=n.dressing;
 const wave=Math.max(1,amb.wave),thing=(key,k)=>{const p=itemPrice(k,wave);return `${keyName(key)} · ${ITEMS[k].name} · ${p} PTS${kit[k]>=ITEMS[k].carry?' (FULL)':need(p)}`;};
 const yours=`YOUR ${held.weapon} · RESERVE ${hand().reserve}/${held.reserve} · DRESSINGS ${bandages}/${AMBUSH.dressingMax}\n${keyName(KEYS.ammo)} · MAGAZINE (${m.rounds} RDS) · ${m.price} PTS${m.full?' (RESERVE FULL)':need(m.price)}   ${keyName(KEYS.dressingBuy)} · FIELD DRESSING · ${dr.price} PTS${dr.full?' (KIT FULL)':need(dr.price)}\n${thing(KEYS.buyFrag,'frag')}   ${thing(KEYS.buySmoke,'smoke')}   ${thing(KEYS.buyFlash,'flash')}`;
 if(n.kind==='crate')return yours;
 const c=CLASSES[n.st.weapon],words=weaponTradeoff(c,gunConfig());return `${keyName(KEYS.interact)} · BUY ${c.weapon} · ${n.price} PTS${need(n.price)} · ${rifleMagazines(c)} MAGAZINES${words?`\n${words}`:''}\n\n${yours}`;}
function ambushInteract(who='me'){const d=amb,u=buyer(who),me=who==='me',n=ambushNear(who);if(!n||n.kind==='crate')return false;if(u.bank.points<n.price){if(me)notify(`NOT ENOUGH POINTS: ${n.price} NEEDED`);return false;}
 if(me&&guesting()){peer.send({type:'buy',k:'E'});return true;} // the host decides; the result arrives with its next snapshot
 u.bank.points-=n.price;$('points').textContent=d.points;
 if(n.kind==='gate'){const name=areaById(n.gate.opens).name.toUpperCase();ambushOpenGate(n.gate.id);d.bought.push(n.gate.id);notify(me?`${name} OPEN`:`YOUR TEAMMATE OPENED THE ${name}`,3);}
 else if(!me){remoteGun=n.st.weapon;const c=CLASSES[remoteGun];remoteWeapon.configure(c);remoteWeapon.reserve=Math.min(c.reserve,c.capacity*(rifleMagazines(c)-1));d.bought.push('mate:'+remoteGun);return true;}
 else{equipGun(n.st.weapon);const c=gunConfig();weapon.configure(c);weapon.reserve=Math.min(c.reserve,c.capacity*(rifleMagazines(c)-1));$('weaponname').textContent=c.weapon+' / '+c.caliber;d.bought.push(n.st.weapon);notify(`${c.weapon} READY · ${rifleMagazines(c)} MAGAZINES`);}
 sound('confirm',.6);return true;}
// B at any crate: one magazine for the rifle you hold, at this wave's price, added to the reserve up to the rifle's limit.
function ambushBuyAmmo(who='me'){const d=amb,u=buyer(who),me=who==='me',n=ambushNear(who);if(!n||n.kind==='gate')return false;const m=n.mag;if(m.full){if(me)notify('RESERVE FULL');return false;}if(u.bank.points<m.price){if(me)notify(`NOT ENOUGH POINTS: ${m.price} NEEDED`);return false;}const add=Math.min(m.rounds,m.config.reserve-u.holding.reserve);
 if(me&&guesting()){peer.send({type:'buy',k:'B'});notify(`+${add} ROUNDS`);sound('confirm',.6);return true;}
 u.bank.points-=m.price;$('points').textContent=d.points;u.holding.reserve+=add;d.bought.push((me?'mag:':'mate:mag:')+(m.config.sidearm?'sidearm':u.gun));if(!me)return true;notify(`+${add} ROUNDS · ${u.holding.reserve} IN RESERVE`);sound('confirm',.6);return true;}
// N at any crate: one field dressing (used with H) at this wave's price, up to dressingMax in the kit (Build 12).
function ambushBuyDressing(who='me'){const d=amb,u=buyer(who),me=who==='me',n=ambushNear(who);if(!n||n.kind==='gate')return false;const dr=n.dressing;if(dr.full){if(me)notify('DRESSING KIT FULL');return false;}if(u.bank.points<dr.price){if(me)notify(`NOT ENOUGH POINTS: ${dr.price} NEEDED`);return false;}
 if(me&&guesting()){peer.send({type:'buy',k:'N'});notify('+1 FIELD DRESSING');sound('confirm',.6);return true;}
 u.bank.points-=dr.price;$('points').textContent=d.points;if(!me){remote.heals++;d.bought.push('mate:dressing');return true;}bandages++;d.bought.push('dressing');notify(`+1 FIELD DRESSING · ${bandages} IN KIT`);sound('confirm',.6);return true;}
function ambushHud(){const d=amb,alive=actors.filter(a=>a.team==='enemy'&&a.hp>0).length,w=waveSpec(Math.max(1,d.wave),d.squad);
 $('objective-label').textContent=`AMBUSH · WAVE ${Math.max(1,d.wave)}`;
 $('objtext').textContent=d.phase==='wave'?`${alive+d.toSpawn} hostiles left · from ${COMPASS[d.bearing/45]}`:d.phase==='decision'?'Extract or stay?':d.wave===0?'Get ready':`Wave ${d.wave} survived`;
 $('distance').textContent=d.phase==='break'?`NEXT WAVE IN ${Math.ceil(d.timer)} S · ${d.open.size}/4 AREAS OPEN`:`${d.survived} WAVES SURVIVED · ${d.open.size}/4 AREAS OPEN`;
 $('capture').style.width=d.phase==='wave'?`${Math.max(0,Math.round(100*(1-(alive+d.toSpawn)/w.count)))}%`:'100%';
 if(d.coop){const m=d.mate;$('matehud').hidden=false;$('matehud').textContent=`TEAMMATE · ${m.left?'DISCONNECTED':m.down?'DOWN':Math.ceil(Math.max(0,remote.hp))+' HP'} · ${m.points} PTS`;}
 $('points').textContent=d.points;$('pointsgain').style.opacity=d.gainTime>0?1:0;
 if(amb.mapOpen)ambushDrawMap();
 const out=!d.down&&!inArena(d.open,player.x,player.z,.3);$('bounds').hidden=!out;if(out)$('bounds').textContent=`OUTSIDE THE ARENA · GET BACK INSIDE THE LINE · ${Math.max(0,AMBUSH.outOfBounds-d.out).toFixed(1)}`;
 $('decision').hidden=d.phase!=='decision';if(d.phase==='decision'){const m=bankMultiplier(d.survived);$('decision-title').textContent=`WAVE ${d.survived} SURVIVED`;$('decision-extract').textContent=`${keyName(KEYS.extract)} · EXTRACT NOW: bank ${Math.round(d.earned*m)} points (${d.earned} × ${m.toFixed(2)})`;$('decision-stay').textContent=`${keyName(KEYS.stay)} · STAY: wave ${d.survived+1} is harder; survive it to bank × ${bankMultiplier(d.survived+1).toFixed(2)}`;$('decision-timer').textContent=`Staying automatically in ${Math.ceil(d.timer)} s`;
  // Co-op: extracting takes both players' choice (a player who is down has none); either one choosing to stay keeps both in.
  if(d.coop){const alone=d.mate.down||d.mate.left,mine=d.vote==='x',theirs=d.mate.vote==='x';if(d.down){$('decision-extract').textContent='YOU ARE DOWN · YOUR TEAMMATE DECIDES';$('decision-stay').textContent=theirs?'YOUR TEAMMATE CHOSE TO EXTRACT':'';}
   $('decision-timer').textContent=`${d.down?'':alone?'Your teammate is down: the choice is yours · ':mine?'You chose to extract · waiting for your teammate · ':theirs?`Your teammate chose to extract · press ${keyName(KEYS.extract)} to go too · `:'Both of you must choose to extract · '}staying automatically in ${Math.ceil(d.timer)} s`;}}}
function ambushTitle(cause){return cause==='extract'?'Extracted.':cause==='bounds'?'Left the arena.':cause==='lost'?'Connection lost.':'Overrun.';}
// Build 16: the pair's report. The run's waves, kills and time, then each player's own kills, points and bank. A player who
// went down banks with the survivor who extracts (Build 17: the run was played together); a run that ends with both down
// banks nothing, as in solo, and so does a player who left. The record is kept under the co-op key, never the solo one.
function ambushCoopReport(cause){const d=amb,t=`${Math.floor(elapsed/60)}m ${Math.floor(elapsed%60)}s`,m=cause==='extract'?bankMultiplier(d.survived):0,wave=Math.max(1,d.wave);$('decision').hidden=$('bounds').hidden=true;
 for(const b of [d,d.mate])b.banked=m&&!b.left?Math.round(b.earned*m):0;
 const line=(who,b)=>`${who}: ${b.kills} kills · ${b.earned} points earned · ${b.banked?`${b.down?'down · ':''}banked ${b.banked} (${b.earned} × ${m.toFixed(2)})`:b.left?'left the run · nothing banked':b.down?'down · nothing banked':'nothing banked'}.`;
 const head=cause==='extract'?`Extracted after wave ${d.survived}.`:cause==='lost'?`The connection to your teammate ended in wave ${wave}.`:d.mate.left?`You went down in wave ${wave} after your teammate left.`:`Both players went down in wave ${wave}.`;
 let text=`${head} ${d.survived} waves survived · ${d.kills+d.mate.kills} kills · ${t}.\n${line('YOU',d)}\n${line('TEAMMATE',d.mate)}`;
 const r=recordBest({wave,banked:d.banked},undefined,BEST_KEY_COOP);d.best=r;if(r.best)text+=r.first?`\nFirst co-op run recorded: wave ${r.best.wave} · ${r.best.banked} banked.`:`\nCo-op personal best: wave ${r.best.wave} · ${r.best.banked} banked${r.improvedWave?' · NEW BEST WAVE':''}${r.improvedBank?' · NEW BEST BANK':''}.`;
 return text;}
// Out of bounds, per player (host): five seconds outside the line puts that player down; the other plays on.
function ambushBounds(dt){const d=amb,m=d.mate,q=remote.g.position;
 if(!d.down){if(inArena(d.open,player.x,player.z,.3))d.out=0;else if((d.out+=dt)>=AMBUSH.outOfBounds){hp=0;ambushDown('me','bounds');}}
 if(state==='playing'&&!m.down&&!m.left){if(inArena(d.open,q.x,q.z,.3))m.out=0;else if((m.out+=dt)>=AMBUSH.outOfBounds){remote.hp=0;ambushDown('mate','bounds');}}}
// A player goes down (host). The run ends only when nobody is left standing; otherwise the wave shrinks to its solo size
// (what has not arrived yet) and a pending extract choice is settled by the player who is left.
function ambushDown(who,cause='killed'){const d=amb,b=who==='mate'?d.mate:d,f=fallen[who==='mate'?'mate':'me'];if(!f.down)Object.assign(f,{down:true,dead:cause==='left',left:REVIVE.wait,progress:0});if(b.down)return;b.down=true;b.downBy=cause;b.vote=null;b.out=0;
 if(who==='me'){hp=0;healing=0;clearInputs();ambushToggleMap(false);}else{remote.hp=0;remote.healing=0;}
 if(d.down&&(d.mate.down||d.mate.left)){finish(false,undefined,'both');return;}
 if(d.phase==='wave'&&d.squad>1&&ambushScale()===1){d.squad=1;d.toSpawn=Math.max(0,Math.min(d.toSpawn,waveSpec(d.wave,1).count-d.spawned));}
 notify(who==='me'?`YOU ARE DOWN · YOUR TEAMMATE HAS ${REVIVE.wait} S TO REVIVE YOU`:cause==='left'?'YOUR TEAMMATE LEFT · THE RUN CONTINUES':`YOUR TEAMMATE IS DOWN · HOLD ${keyName(KEYS.interact)} OVER THEM TO REVIVE`,5);
 if(d.phase==='decision')ambushResolve();}
// The connection ended for good in a co-op Ambush run: the host plays on alone, the guest's run ends with what it knows.
function ambushLinkLost(){const d=amb;if(peer.role==='host'){d.mate.left=true;remote.g.visible=false;fallen.mate.dead=true;humanDown('mate','left');if(!d.mate.down)ambushDown('mate','left');}else finish(false,undefined,'lost');}
// The extract choice in co-op. Extracting ends the run for both, so it takes both players' choice; choosing to stay settles
// it at once, and so does the timer (stay), as in solo. A player who is down has no vote.
function ambushChoose(extract){const d=amb;if(!d.coop){ambushDecide(extract);return;}if(d.phase!=='decision'||d.down)return;if(guesting()){peer.send({type:'vote',x:!!extract});if(extract)d.vote='x';return;}ambushVote('me',extract);}
function ambushVote(who,extract){const d=amb,b=who==='mate'?d.mate:d;if(d.phase!=='decision'||b.down||b.left)return;if(!extract){ambushDecide(false);return;}b.vote='x';ambushResolve();}
function ambushResolve(){const d=amb,up=[d,d.mate].filter(b=>!b.down&&!b.left);if(d.phase==='decision'&&up.length&&up.every(b=>b.vote==='x'))ambushDecide(true);}
// What the host tells the guest about the run, from the guest's side ('me' is the guest): with every snapshot.
function ambushWire(){const d=amb,bank=b=>[b.points,b.earned,b.kills||0,b.down?1:0,Math.round((b.out||0)*10)/10,b.vote==='x'?1:0,b.left?1:0];return {w:d.wave,ph:d.phase,t:Math.round(d.timer*10)/10,n:d.toSpawn,b:d.bearing??0,sv:d.survived,q:d.squad,g:GATES.reduce((m,g,i)=>d.gates.has(g.id)?m|1<<i:m,0),me:bank(d.mate),mate:bank(d)};}
const AMB_PHASES=['break','wave','decision'];
// Guest: take the host's word for the run. Barricades the host no longer has are opened here the same way a purchase
// opens them, so the arena, its edge, the map and the markings are the host's.
function ambushApply(s){const d=amb,m=d.mate;if(!s||typeof s!=='object'||!AMB_PHASES.includes(s.ph)||!Number.isInteger(s.w)||s.w<0||!Number.isInteger(s.g)||!finiteArray(s.me,7)||!finiteArray(s.mate,7))return false;
 const squad=s.q===2?2:1,bearing=Number.isFinite(s.b)?((Math.round(s.b/45)%8)+8)%8*45:0,survived=Number.isInteger(s.sv)?s.sv:d.survived;
 if(s.w!==d.wave&&s.ph==='wave'){aiTune=null;radio(`Command: Wave ${s.w} inbound from the ${COMPASS_WORDS[bearing/45]}, ${waveSpec(s.w,squad).count} hostiles.`);}
 if(survived>d.survived)notify(`WAVE ${survived} SURVIVED`,3);else if(d.phase==='decision'&&s.ph==='break')notify(`STAYING: SURVIVE WAVE ${s.w+1} TO BANK ×${bankMultiplier(s.w+1).toFixed(2)}`,4);
 Object.assign(d,{wave:s.w,phase:s.ph,timer:Number.isFinite(s.t)?s.t:0,toSpawn:Number.isInteger(s.n)?s.n:0,bearing,survived,squad});
 GATES.forEach((g,i)=>{if(!(s.g>>i&1)&&ambushOpenGate(g.id))notify(`${areaById(g.opens).name.toUpperCase()} OPEN`,3);});
 const [p,e,k,dn,out,v]=s.me;if(e>d.earned){d.gainTime=1.2;$('pointsgain').textContent=`+${e-d.earned}${e-d.earned===AMBUSH.killPoints+AMBUSH.headshotBonus?' HEADSHOT':''}`;}
 Object.assign(d,{points:p,earned:e,kills:k,out,vote:v?'x':d.phase==='decision'?d.vote:null});$('points').textContent=d.points;
 if(dn&&!d.down){d.down=true;hp=0;healing=0;clearInputs();ambushToggleMap(false);notify(`YOU ARE DOWN · YOUR TEAMMATE HAS ${REVIVE.wait} S TO REVIVE YOU`,5);}else if(!dn&&d.down)d.down=false;
 const was=m.down;Object.assign(m,{points:s.mate[0],earned:s.mate[1],kills:s.mate[2],down:!!s.mate[3],out:s.mate[4],vote:s.mate[5]?'x':null,left:!!s.mate[6]});if(m.down&&!was)notify('YOUR TEAMMATE IS DOWN · THE RUN CONTINUES',5);return true;}
// Guest: the purchase prompt is worked out here from the host's state; everything else arrives with the snapshots.
function ambushGuestTick(dt){const d=amb;$('interact').textContent=d.down?'':ambushPrompt();d.gainTime=Math.max(0,d.gainTime-dt);}
function ambushReport(cause){if(amb.coop)return ambushCoopReport(cause);const d=amb,t=`${Math.floor(elapsed/60)}m ${Math.floor(elapsed%60)}s`;$('decision').hidden=$('bounds').hidden=true;let text;
 if(cause==='extract'){const m=bankMultiplier(d.survived);d.banked=Math.round(d.earned*m);text=`Extracted after wave ${d.survived}. Banked ${d.banked} points (${d.earned} earned × ${m.toFixed(2)}). ${d.survived} waves survived · ${kills} kills · ${t}.`;}
 else{d.banked=0;text=`${cause==='bounds'?'You left the arena':'You were killed'} in wave ${Math.max(1,d.wave)}. Nothing banked. ${d.survived} waves survived · ${kills} kills · ${d.earned} points earned · ${t}.`;}
 // Build 11: personal best (browser storage only; absent or blocked storage just leaves the line out).
 const r=recordBest({wave:Math.max(1,d.wave),banked:d.banked});d.best=r;if(r.best)text+=r.first?` First run recorded: wave ${r.best.wave} · ${r.best.banked} banked.`:` Personal best: wave ${r.best.wave} · ${r.best.banked} banked${r.improvedWave?' · NEW BEST WAVE':''}${r.improvedBank?' · NEW BEST BANK':''}.`;
 return text;}
function missionTick(dt){if(mode==='ambush'){ambushTick(dt);return;}const dist=player.distanceTo(objectivePoint());if(mode!=='skirmish'&&stage===0){$('interact').textContent=player.distanceTo(intel)<5?'E · RECOVER ROUTE LOG':'';}else{$('interact').textContent='';}if(mode==='skirmish'||stage===1){const friends=(!fallen.me.down&&player.distanceTo(target)<9?1:0)+(remote.g.visible&&!fallen.mate.down&&remote.g.position.distanceTo(target)<9?1:0);const enemies=actors.filter(a=>a.team==='enemy'&&a.hp>0&&a.g.position.distanceTo(target)<15).length;const required=mode==='skirmish'?45:25;if(friends>0&&enemies===0)progress=Math.min(required,progress+dt);if(progress>=required){if(mode==='skirmish')finish(true);else{stage=2;progress=0;radio('Command: Signal restored. Convoy has diverted to safety. Viper, move to the eastern courtyard for extraction.');}}}else if(stage===2){if(player.distanceTo(extract)<5&&(mode!=='coop'||remote.g.position.distanceTo(extract)<5)){progress+=dt;if(progress>=5)finish(true);}else progress=0;}}
function hudObjective(dist){if(LOOK){lookHud();return;}if(mode==='ambush'){ambushHud();return;}const required=mode==='skirmish'?45:stage===1?25:5;$('objective-label').textContent=mode==='skirmish'?'SECURE THE RELAY':`${String(stage+1).padStart(2,'0')} / BROKEN SIGNAL`;$('objtext').textContent=mode==='skirmish'||stage===1?'Restore and hold the relay':stage===0?'Recover the route log':'Reach the extraction courtyard';$('distance').textContent=`${Math.round(dist)} M · ${mode==='skirmish'||stage===1?`${Math.floor(progress)} / ${required} SEC`:stage===0?'WESTERN FIELD OFFICE':mode==='coop'?'BOTH PLAYERS REQUIRED':'HOLD FOR EXTRACTION'}`;$('capture').style.width=(stage===0&&mode!=='skirmish'?0:progress/required*100)+'%';ringmesh.visible=mode==='skirmish'||stage===1;extractionMark.visible=mode!=='skirmish'&&stage===2;intelObject.visible=mode!=='skirmish'&&stage===0;}
// ---- Build 19 equipment: a sidearm beside the rifle, a knife on its own key, and three throwables (equipment.js holds the
// numbers and the pure rules). Nothing here draws a seeded random number or touches an enemy until a player uses an item, so
// Story, Skirmish and solo Ambush replay their recorded runs. In co-op the host decides everything (what a shot, a thrust, a
// blast or a flash does, how many rounds and throwables the guest has) and the guest's actions are judged by what the guest
// saw and counted from when the guest began them, as its rifle shots are since Build 18.
const sidearm=new WeaponState(SIDEARM),remoteSide=new WeaponState(SIDEARM),kit={frag:0,smoke:0,flash:0},remoteKit={frag:0,smoke:0,flash:0};
let slot=0,drawing=0,remoteSlot=0,remoteDraw=0,knifeCool=0,knifeShow=0,remoteKnifeAt=-9,item='frag',cooking=null,blind=0,nadeId=0;
function hand(){return slot?sidearm:weapon;}
function handConfig(){return slot?SIDEARM:gunConfig();}
function remoteHand(w=remoteSlot){return w?remoteSide:remoteWeapon;}
function remoteConfig(w=remoteSlot){return w?SIDEARM:CLASSES[remoteGun];}
function weaponLabel(){const c=handConfig();$('weaponname').textContent=c.weapon+' / '+c.caliber;}
function equipReset(){const L=loadoutFor(mode);slot=remoteSlot=0;drawing=remoteDraw=knifeCool=knifeShow=blind=0;remoteKnifeAt=-9;cooking=null;item='frag';for(const w of [sidearm,remoteSide]){w.configure(SIDEARM);w.reserve=L.sidearmReserve;}for(const k of ITEM_ORDER)kit[k]=remoteKit[k]=L[k];nadeClear();viewmodel.setSidearm(false);$('flashed').style.opacity=0;}
// The weapon in hand changes; a reload of the weapon put away is dropped, and the new one can fire after its draw time.
function swapWeapon(to=slot?0:1){if(state!=='playing'||hostPaused||spectating()||cooking||to===slot)return false;hand().reloadRemaining=0;slot=to;drawing=slot?DRAW.sidearm:DRAW.rifle;aim=aimToggle=trigger=false;viewmodel.setSidearm(!!slot);weaponLabel();sound('step',1.2);if(guesting())peer.send({type:'swap',slot,at:elapsed});return true;}
function nextItem(){item=ITEM_ORDER[(ITEM_ORDER.indexOf(item)+1)%ITEM_ORDER.length];notify(`${ITEMS[item].name} × ${kit[item]}`,1.5);}
function gearLine(){const other=slot?gunConfig():SIDEARM,w=slot?weapon:sidearm;return `${keyName(KEYS.swap)} · ${other.weapon} ${w.ammo}/${w.reserve}   ${keyName(KEYS.melee)} · KNIFE   ${keyName(KEYS.throw)} · ${ITEMS[item].name} × ${kit[item]}   ${keyName(KEYS.item)} · ${ITEM_ORDER.map(k=>`${ITEMS[k].name} ${kit[k]}`).join(' / ')}`;}
// The knife. The nearest character in reach with no wall in between is struck: an enemy for KNIFE.front, or KNIFE.back
