window.dustline={snapshot:()=>({version:4,state,mode,classId,stage,rifleLoaded:viewmodel.loaded,world:{enterableBuildings:interiors.length,officeDoorClear:!blocked(...WORLD.log.door),officeInteriorClear:!blocked(...WORLD.log.at),extractionClear:!blocked(...WORLD.extraction)},health:hp,ammo:weapon.ammo,reserve:weapon.reserve,reloadRemaining:weapon.reloadRemaining,fireCooldown:weapon.cooldown,magazineSize:gunConfig().capacity,performance:{fps:Math.round(fps),drawCalls:renderer.info.render.calls,triangles:renderer.info.render.triangles,renderScale,staticDrawsRemoved:batching.removedDraws},lockFailure,cursorHidden:document.body.classList.contains('in-play'),pointerLocked:document.pointerLockElement===renderer.domElement,captureSeconds:progress,kills,position:{x:player.x,z:player.z},connection:{role:peer.role,connected:peer.connected},actors:actors.filter(a=>a.g.visible).map(a=>({team:a.team,health:a.hp,x:a.g.position.x,z:a.g.position.z}))})};
// Build 22: on a map to look at, the page can put the viewer somewhere (used to measure and to check the block).
if(LOOK)window.dustline.stand=(x,z,turn=0,tip=0,up=0)=>{player.set(x,groundY(x,z),z);yaw=turn;pitch=tip;lookView=[x,player.y+1.7+up,z,turn,tip];camera.position.set(x,lookView[1],z);camera.rotation.set(tip,turn,0);renderer.shadowMap.needsUpdate=true;renderer.render(scene,camera);return {x,y:player.y,z,draws:renderer.info.render.calls,triangles:renderer.info.render.triangles,models:built?.stats};};
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_mission_status',description:'Read game mode, class, reload state, cursor capture, health and mission progress.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw new Error('Expected an empty object.');return window.dustline.snapshot();}})).catch(()=>{});}catch{}}
